import heapq

def top_k_frequent(lists, k):
    # Create a dictionary to store the frequency of each integer
    freq = {}
    for list in lists:
        for i in list:
            if i not in freq:
                freq[i] = 0
            freq[i] += 1

    # Create a min heap to store the top k frequent integers
    heap = []

    # Iterate over the dictionary and add the top k frequent integers to the heap
    for i in freq:
        if len(heap) < k:
            heapq.heappush(heap, (freq[i], i))
        elif freq[i] > heap[0][0]:
            heapq.heappop(heap)
            heapq.heappush(heap, (freq[i], i))

    # Return the top k frequent integers in the heap
    return [i for _, i in heap]

