    # Initialize a dictionary to store the number of ways to fill each row
    ways = {}

    # Iterate through each row of the board
    for i in range(len(board)):
        # If the current row is already filled with 2 x 1 dominoes, continue
        if all(j == 2 for j in ways[i]):
